class Message:
    def __init__(self, bot, data):
        self.bot = bot
        self.text = data.get("text")
        self.chat_id = data.get("chat", {}).get("id")
        self.user_id = data.get("from", {}).get("id")
        self.first_name = data.get("from", {}).get("first_name")
        self.username = data.get("from", {}).get("username")
        self.message_id = data.get("message_id")

    def answer(self, text, reply_markup=None):
        return self.bot.send_message(self.chat_id, text, reply_markup)

    def reply(self, text, reply_markup=None):
        return self.bot.send_message(
            self.chat_id,
            text,
            reply_markup=reply_markup,
            reply_to_message_id=self.message_id,
        )


class CallbackQuery:
    def __init__(self, bot, data):
        self.bot = bot
        self.data = data

        self.callback_data = data.get("data")

        user = data.get("from", {})
        self.user_id = user.get("id")
        self.first_name = user.get("first_name")

        self.message = Message(bot, data.get("message", {}))

        self.chat_id = self.message.chat_id

    def answer(self, text, reply_markup=None):
        return self.bot.send_message(self.chat_id, text, reply_markup=reply_markup)
